		filepath.Base(publication.Candidate) != publication.Candidate ||
		strings.ContainsAny(publication.Candidate, `/\`) ||
		decodeErr != nil || len(decodedSHA) != sha256.Size || publication.SHA256 != strings.ToLower(publication.SHA256) ||
