		t.Fatalf("plan transcripts = %+v", plan.Transcripts)
	}
	if plan.Records == 0 {
		t.Fatal("plan must count derived records")
	}
	hasFTS := false
	for _, store := range plan.DerivedStores {
		if store.Path == historyFTSDBRelPath() {
