		"corpus.sqlite-shm":     []byte("external shm sentinel\n"),
		"corpus.sqlite-journal": []byte("external journal sentinel\n"),
	}
	for name, data := range externalFiles {
		if err := os.WriteFile(filepath.Join(external, name), data, 0o600); err != nil {
