	if err := recoverPatternCorpusPublicationLocked(brainDir); err != nil {
		return err
	}
	manifest, err := loadPatternCorpusManifest(brainDir)
	if err != nil {
		return err
	}
	guard, err := loadSessionReadGuard(brainDir, manifest)
	if err != nil {
