func requirePatternCorpusAvailable(brainDir string) error {
	if err := validatePatternCorpusReadSafety(brainDir); err != nil {
		return err
	}
	_, present, err := privacyArtifactInfo(brainDir, patternCorpusPath, "pattern corpus")
	if err != nil {
