}

// buildPatternCorpus (re)indexes the brain's sessions into patterns/corpus.sqlite.
// Idempotent: unchanged sessions are skipped, changed sessions are replaced in a
// transaction, removed transcripts are pruned, and an indexer-version bump forces
// a full re-index. Deterministic and token-free.
func buildPatternCorpus(brainDir string, now time.Time) error {
	// Session manifests, exported transcripts, facts, tombstones, corpus
	// verifiers, and purge all use this lock for their mutation boundary. The
	// deterministic build can therefore take a coherent input snapshot and a
	// purge cannot verify clean before a stale corpus is published.
	return withBrainWriteLock(brainDir, func() error {
		return buildPatternCorpusLocked(brainDir, now)
	})
}

func buildPatternCorpusLocked(brainDir string, now time.Time) error {
	if err := recoverPatternCorpusPublicationLocked(brainDir); err != nil {
		return err
	}
	manifest, err := loadPatternCorpusManifest(brainDir)
	if err != nil {
		return err
	}
	guard, err := loadSessionReadGuard(brainDir, manifest)
	if err != nil {
		return err
	}
	path, cleanup, err := preparePatternCorpusStaging(brainDir)
	if err != nil {
		return err
	}
	defer cleanup()
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		return err
	}
	closed := false
	defer func() {
		if !closed {
			_ = db.Close()
		}
	}()
	for _, p := range []string{"PRAGMA busy_timeout=5000", "PRAGMA foreign_keys=ON"} {
		if _, err := db.Exec(p); err != nil {
			return err
		}
	}
	for _, stmt := range patternCorpusSchema {
		if _, err := db.Exec(stmt); err != nil {
			return fmt.Errorf("corpus schema: %w", err)
		}
	}

	// Indexer-version bump forces a full re-index (parser/extractor changed).
	if stored := corpusMeta(db, "pattern_indexer_version"); stored != strconv.Itoa(patternIndexerVersion) {
		if _, err := db.Exec(`DELETE FROM episodes`); err != nil { // cascades children
			return err
		}
		if _, err := db.Exec(`DELETE FROM indexed_sessions`); err != nil {
			return err
		}
	}

	repoKey := ""
	if manifest != nil {
		repoKey = manifest.RepoKey
	}
	var sessions []exportSession
	if manifest != nil && manifest.Sources != nil && manifest.Sources.Sessions != nil {
		sessions = manifest.Sources.Sessions.Sessions
	}
	// Session tombstones (Phase 4): excluded sessions and duplicate manifest
	// entries that alias an excluded transcript never enter the corpus; dropping
	// them from the present set prunes previously indexed rows below.
	sessions = guardExportSessions(guard, sessions)
	// Optional enrichment source: durable facts, branch-scoped. Missing is
	// empty, but corrupt/unsafe state fails closed and tombstoned-only facts are
	// filtered before they can be linked back into a rebuilt corpus.
	factsByBranch, err := loadAllFactBranchesForPrivacy(brainDir)
	if err != nil {
		return err
	}
	for branch, facts := range factsByBranch {
		factsByBranch[branch] = guardFactRecords(guard, facts)
	}

	present := map[string]bool{}
	for _, s := range sessions {
		rel := strings.TrimSpace(s.TranscriptPath)
		if rel == "" {
			continue
		}
		id := repoKey + "/" + filepath.ToSlash(rel)
		content, size, mtime, sha, readErr := readPatternCorpusTranscript(context.Background(), brainDir, filepath.ToSlash(rel))
		if readErr != nil {
			if errors.Is(readErr, os.ErrNotExist) {
				return &historySessionInventoryError{
					Path:   filepath.ToSlash(rel),
					Reason: "manifest-listed canonical transcript is missing; refusing a partial corpus publication",
					Err:    readErr,
				}
			}
			return readErr
		}
		present[id] = true
		if corpusSessionUnchanged(db, id, size, mtime, sha) {
			continue
		}
		if err := indexSessionIntoCorpus(db, repoKey, s, id, rel, content, size, mtime, sha, factsByBranch); err != nil {
			return err
		}
	}

	// Prune sessions no longer in the manifest (deleted transcripts).
	if err := pruneCorpusSessions(db, present); err != nil {
		return err
	}

	// Link episodes to semantic symbols (if a semantic index exists), then
// executeSessionPurge applies the plan under the already-held write lock:
// tombstone first (so a crash mid-purge can only leave the session excluded,
// never resurrected), then physical deletion, then a clean rebuild of the
// history projection from the surviving truth.
func executeSessionPurge(brainDir, sessionID string, plan sessionPurgePlan, now time.Time) error {
	return executeSessionCleanup(brainDir, sessionID, plan, now, "purged", false)
}

// beforeSessionAbstractPrivacyCleanup is a deterministic crash/failure seam
// after the tombstone and durable scope exist but before abstract artifacts are
// removed. Production leaves it as a no-op.
var beforeSessionAbstractPrivacyCleanup = func() error { return nil }

// executeSessionCleanup is the shared exclude/purge executor: tombstone,
// transcript deletion (purge only), derived-store deletion, fact/episode/
// cache filtering, then the rebuild. Every deletion error propagates;
// the tombstone-first order keeps a failed run resumable and the session
// unreadable in the meantime. Progress is a durable transaction record:
// each stage transition is persisted before the stage runs, and a
// failure leaves an error state naming what stopped it.
func executeSessionCleanup(brainDir, sessionID string, plan sessionPurgePlan, now time.Time, reason string, keepTranscripts bool) (err error) {
	// Operational publication state is classified before the transaction or
	// tombstone changes. A newer/corrupt/unsafe marker is owned by a producer we
	// cannot safely supersede, so cleanup must preserve both it and its candidate.
	if _, _, _, markerErr := loadPatternCorpusPublicationForPrivacy(brainDir); markerErr != nil {
		return markerErr
	}
	stones, _, err := loadSessionTombstonesChecked(brainDir)
	if err != nil {
		return err
	}
	operation := "purge"
	if keepTranscripts {
		operation = "exclude"
	}
	tx := privacyTransaction{
		SessionID: sessionID, Operation: operation,
		State: privacyStateRequested, StartedAt: now,
		Artifacts:   append(append(append([]purgeArtifact(nil), plan.Transcripts...), plan.DerivedStores...), plan.WorkMetadata...),
		SessionRefs: append([]string(nil), plan.SessionRefs...),
	}
	if txErr := writePrivacyTransaction(brainDir, tx, now); txErr != nil {
		return txErr
	}
	defer func() {
		if err == nil {
			return
		}
		// Best-effort durable failure state; the command error is authoritative.
		tx.State = privacyStateError
		message := err.Error()
		if len(message) > privacyTransactionErrorMaxBytes {
			message = message[:privacyTransactionErrorMaxBytes]
		}
		tx.Error = message
		_ = writePrivacyTransaction(brainDir, tx, now)
	}()
	advance := func(state string) error {
		tx.State = state
		tx.Error = ""
		return writePrivacyTransaction(brainDir, tx, now)
	}
	stones.Excluded[sessionID] = sessionTombstone{At: now, Reason: reason}
	if err := saveSessionTombstones(brainDir, stones); err != nil {
		return err
	}
	if err := advance(privacyStateGuarded); err != nil {
		return err
	}
	if err := advance(privacyStateRebuilding); err != nil {
		return err
	}
	// Remove a supported marker first, with a fresh classification and exact
	// identity check. This prevents a stale plan from deleting its candidate
	// before discovering that a forward-version marker took ownership.
	if err := removePatternCorpusPublicationForPrivacy(brainDir); err != nil {
		return fmt.Errorf("delete pattern corpus publication marker: %w", err)
	}
	if !keepTranscripts {
		for _, artifact := range plan.Transcripts {
			path := filepath.Join(brainDir, filepath.FromSlash(artifact.Path))
			if err := rejectSymlinkPathComponents(brainDir, filepath.FromSlash(artifact.Path)); err != nil {
				if os.IsNotExist(err) {
					continue
				}
				return err
			}
			if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
				return err
			}
		}
	}
	for _, artifact := range plan.DerivedStores {
		if artifact.Path == patternCorpusPublicationMarkerPath {
			continue // classified and identity-checked above
		}
		if err := removePrivacyDerivedStoreArtifact(brainDir, artifact.Path); err != nil {
			return fmt.Errorf("delete derived store %s: %w", artifact.Path, err)
		}
	}
	transcriptRels := map[string]bool{}
	for _, artifact := range plan.Transcripts {
		transcriptRels[normalizePrivacyTranscriptPath(artifact.Path)] = true
	}
	deletedFacts, strippedAnchors, err := purgeSessionFacts(brainDir, sessionID, transcriptRels)
	if err != nil {
		return err
	}
	// Rebuild sources.facts from what survived. Every other fact mutation
	// (remember, review, promote, retract, gc, sync) resummarizes the manifest;
	// privacy cleanup deleted facts and did not, so the manifest kept declaring
	// facts this function had just removed. That is indistinguishable on disk
	// from the corruption the integrity cross-check exists to catch, and would
	// make a sanctioned purge report itself as data loss. This runs under the
	// caller's brain write lock.
	if deletedFacts > 0 || strippedAnchors > 0 {
		if err := updateFactSourceManifestLocked(brainDir, now); err != nil {
			return err
		}
	}
	if _, _, err := filterEpisodesFile(brainDir, sessionID, transcriptRels, true); err != nil {
		return err
	}
	// Strip the session linkage from the derived entity index. Sweeping against
	// the WHOLE tombstone set, not just this session, repairs an index rebuilt
	// by an `entities backfill` that ran between two cleanups; the builder now
	// filters too, so a later rebuild stays clean by construction.
	if _, err := filterEntityIndexSessions(brainDir, stones.Excluded, true); err != nil {
		return err
	}
	if err := purgeDistillCacheEntries(brainDir, sessionID); err != nil {
		return err
	}
	cleanupManifest, manifestErr := loadBrainManifest(brainDir)
	if manifestErr != nil {
		return manifestErr
	}
	refs := sessionRefsForSessionID(brainDir, cleanupManifest, sessionID)
