	}
	stagePath := filepath.Join(tempDir, "corpus.sqlite")
	stage, err := os.OpenFile(stagePath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	cleanup := func() {
		if stage != nil {
			_ = stage.Close()
		}
		_ = os.RemoveAll(tempDir)
